"""Build the six offline product experiments with a shared visual language.

This script writes only the six named HTML experiments, not course lessons.
Run with the course Python; no external packages or network are required.
"""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
# Colours come only from course/visuals/theme-tokens.css (6.0, D2). Old literals -> tokens: white page -> --bg;
# white controls and cards -> --paper; pale teal / amber / blue fills -> --act-soft / --hint-soft / --accent-soft;
# grey fills and borders -> --surface / --line / --line-strong; dashed wait border -> --muted; focus -> --focus;
# text on blue buttons -> --bg; variables blue/teal/orange/pale -> --accent/--act/--hint/--surface;
# range sliders -> --act.
CSS = """
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 'Segoe UI',Arial,sans-serif}main{max-width:960px;margin:auto;padding:20px}h1{font-size:23px;line-height:1.25;letter-spacing:-.025em;margin:3px 0 10px}h2{font-size:16px;margin:0 0 10px}p{margin:8px 0 14px}.kicker{color:var(--act);font-size:12px;font-weight:700;letter-spacing:.09em;text-transform:uppercase}.intro,.note{color:var(--muted)}.note{font-size:13px;margin:14px 0 0}.controls{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:12px;margin:18px 0}.control{display:block;padding:12px 14px;background:var(--surface);border-radius:8px;min-width:0}.label{display:flex;align-items:baseline;justify-content:space-between;gap:8px;font-size:14px;font-weight:600;margin-bottom:8px}.label output{white-space:nowrap;color:var(--accent);font-variant-numeric:tabular-nums}input,select,button{font:inherit}input[type=range]{display:block;width:100%;margin:12px 0 4px;accent-color:var(--act)}select{display:block;width:100%;min-width:0;max-width:100%;padding:8px;border:1px solid var(--line-strong);background:var(--paper);border-radius:5px;color:var(--ink);font-size:14px}button{min-height:42px;padding:8px 14px;background:var(--accent);border:1px solid var(--accent);border-radius:6px;color:var(--bg);font-weight:600;cursor:pointer}button.secondary{background:var(--paper);color:var(--accent)}button:disabled{background:var(--surface);border-color:var(--line);color:var(--muted);cursor:default}:focus-visible{outline:3px solid var(--focus);outline-offset:3px}.buttons{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0 16px}.figure{border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:16px 0;margin:16px 0}.figure-caption{font-size:13px;color:var(--muted);margin:12px 0 0}.result{background:var(--act-soft);border-left:4px solid var(--act);padding:12px 14px;margin:16px 0 0;line-height:1.5}.result.warn{background:var(--hint-soft);border-color:var(--hint)}.result strong{display:block;margin-bottom:4px}.badge{display:inline-block;font-size:12px;font-weight:700;padding:2px 8px;border-radius:4px;background:var(--act-soft);color:var(--act)}.badge.warn{background:var(--hint-soft);color:var(--hint)}.badge.neutral{color:var(--muted);background:var(--surface)}.legend{display:flex;gap:8px 16px;flex-wrap:wrap;font-size:12px;color:var(--muted);margin-bottom:14px}.legend span:before{content:'';display:inline-block;width:11px;height:11px;margin-right:5px;background:var(--accent);vertical-align:-1px}.legend .pause:before{background:var(--line)}.legend .output:before{background:var(--act)}.legend .endpoint:before{width:3px;background:var(--hint)}.stat-row{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.stat{background:var(--surface);padding:6px 10px;border-radius:5px;font-size:13px}.stat b{color:var(--accent);font-variant-numeric:tabular-nums}code,pre{font-family:Consolas,'Courier New',monospace;font-size:.92em}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--surface);padding:12px;margin:10px 0;border-radius:5px}.diagram-flow{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px;margin:12px 0}.flow-step{position:relative;padding:12px;border:1px solid var(--line);border-radius:6px;min-width:0;background:var(--paper)}.flow-step:not(:last-child):after{content:'→';position:absolute;right:-17px;top:32px;color:var(--muted)}.flow-step b{display:block;font-size:14px}.flow-step p{font-size:13px;margin:8px 0 0;color:var(--muted)}.flow-step.pass{border-top:3px solid var(--act)}.flow-step.blocked{border-top:3px solid var(--hint);background:var(--hint-soft)}.flow-step.skipped{background:var(--surface);border-style:dashed}.flow-step .step-number{font-size:11px;color:var(--muted);letter-spacing:.04em;text-transform:uppercase}.timeline{position:relative;height:38px;background:var(--surface);border:1px solid var(--line);border-radius:4px}.interval{position:absolute;top:6px;bottom:6px;border-radius:2px;background:var(--accent)}.interval.silence{background:var(--line)}.interval.buffer{background:var(--act);opacity:.88}.interval.wait{background:var(--line);border:1px dashed var(--muted)}.interval.work{background:var(--accent)}.endpoint-line{position:absolute;top:-5px;bottom:-5px;border-left:2px dashed var(--hint);z-index:2}.axis{position:relative;height:28px;color:var(--muted);font-size:11px;font-variant-numeric:tabular-nums}.axis span{position:absolute;top:4px;transform:translateX(-50%)}.axis span:first-child{transform:none}.axis span:last-child{transform:translateX(-100%)}.track-label{display:flex;justify-content:space-between;align-items:baseline;gap:8px;font-size:14px;font-weight:600;margin:13px 0 6px}.track-label small{font-weight:400;color:var(--muted);font-size:12px}.event-list{padding:0;list-style:none;margin:8px 0}.event-list li{display:flex;gap:8px;align-items:baseline;margin:8px 0;font-size:14px}.event-list b{font-variant-numeric:tabular-nums;white-space:nowrap;color:var(--hint)}.source-quote{margin:12px 0;padding:14px 16px;border-left:3px solid var(--line-strong);background:var(--surface)}mark{color:var(--ink);background:var(--accent-soft);border-radius:2px;padding:2px 0}.check-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.check-item{display:flex;gap:10px;padding:12px;background:var(--surface);border:1px solid var(--line);border-radius:6px;cursor:pointer;line-height:1.4}.check-item input{flex:0 0 auto;width:19px;height:19px;accent-color:var(--act);margin-top:1px}.check-item small{display:block;color:var(--muted);font-size:12px;margin-top:3px}.progress-track{height:10px;border-radius:8px;background:var(--line);margin:8px 0;overflow:hidden}.progress-fill{height:100%;background:var(--act);transition:width .15s}.states{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:16px 0}.state{position:relative;border:1px solid var(--line);border-radius:6px;padding:12px;background:var(--surface)}.state:not(:last-child):after{content:'→';position:absolute;top:26px;right:-14px;color:var(--muted)}.state.current{border:2px solid var(--accent);background:var(--accent-soft)}.state.done{border-top:3px solid var(--act);background:var(--act-soft)}.state b{display:block;font-size:14px}.state small{font-size:12px;color:var(--muted)}.history{font-size:13px;color:var(--muted);margin:10px 0;padding-left:20px}.history li{margin:4px 0}.gate{display:flex;align-items:center;gap:12px;border:1px solid var(--line);padding:12px;border-radius:6px;margin:10px 0}.gate>span{font-size:24px;color:var(--act);flex:0 0 28px}.gate.blocked>span{color:var(--hint)}.gate p{margin:2px 0;color:var(--muted);font-size:13px}.gate strong{font-size:14px}
@media(max-width:560px){main{padding:14px}h1{font-size:21px}.controls{gap:8px;margin:14px 0}.control{padding:10px 12px}.diagram-flow{grid-template-columns:1fr;gap:18px}.flow-step:not(:last-child):after{content:'↓';top:auto;right:auto;left:15px;bottom:-19px}.flow-step{padding:10px 12px}.flow-step p{margin-top:3px}.check-list{grid-template-columns:1fr}.states{gap:9px}.state{padding:9px 7px}.state:not(:last-child):after{right:-9px;font-size:12px}.state b{font-size:12px}.state small{font-size:11px}.track-label{flex-wrap:wrap;gap:0 8px}.event-list li{flex-wrap:wrap;gap:0 8px}.result{padding:10px 12px}.legend{gap:6px 12px}.axis{font-size:10px}}
@media(prefers-reduced-motion:reduce){*{transition:none!important}}
.request-row .figure-caption{margin-top:5px}.request-row .track-label{margin:10px 0 4px}.request-row .timeline{height:30px}
"""


def page(key, title, intro, body, js):
    # Keep feedback next to the controls; detailed traces follow below.
    if key != "M15-L06":
        result = '<div id="result" class="result" aria-live="polite"></div>'
        body = body.replace(result, "")
        at = body.index('<pre id="proposal"') if key == "M14-L06" else body.index('<div class="figure"')
        body = body[:at] + result + body[at:]
    html = f'''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{title}</title><link rel="stylesheet" href="theme-tokens.css"><style>{CSS}</style></head><body><main>
<div class="kicker">Численный опыт · {key}</div><h1>{title}</h1><p class="intro">{intro}</p>
{body}
</main><script>{js}</script><script src="visual-frame.js"></script></body></html>'''
    (ROOT / f"course/visuals/{key}.html").write_text(html, encoding="utf-8", newline="\n")


BASE_JS = """
const $=id=>document.getElementById(id);
const pct=(v,max)=>100*v/max;
const interval=(start,end,max,kind)=>`<span class="interval ${kind}" style="left:${pct(start,max)}%;width:${pct(end-start,max)}%"></span>`;
const marker=(at,max)=>`<span class="endpoint-line" style="left:${pct(at,max)}%" aria-hidden="true"></span>`;
const axis=(max,ticks)=>`<div class="axis" aria-hidden="true">${ticks.map(t=>`<span style="left:${pct(t,max)}%">${t}</span>`).join('')}</div>`;
"""


def build():
    page("M13-L06", "Кто дождётся свободного worker?", "Четыре запроса приходят одновременно. Один worker обрабатывает запрос за 60 мс. Предскажи, сколько ответов будут иметь коды 200, 503 и 504.", '''
<div class="controls">
<label class="control"><span class="label">Вместимость <output id="capacity-value" for="capacity">3 запроса</output></span><input id="capacity" type="range" min="1" max="4" value="3"><small>Включая запрос в работе</small></label>
<label class="control"><span class="label">Лимит ожидания <output id="wait-value" for="wait">90 мс</output></span><input id="wait" type="range" min="0" max="200" step="10" value="90"><small>Начало работы допустимо при wait ≤ лимита</small></label>
</div>
<div class="figure" aria-label="Расписание четырёх запросов"><div class="legend"><span>Работа</span><span class="pause">Ожидание</span><span class="endpoint">Лимит ожидания</span></div><div id="schedule"></div><div id="counts" class="stat-row"></div><p class="figure-caption">Общая ось времени: 0–240 мс. Запросы сверх вместимости отвергаются при поступлении.</p></div>
<div id="result" class="result" aria-live="polite"></div>
<p class="note">Идеальное расписание, а не измерение HTTP. Все запросы поступили в момент 0; освобождение места позже не возвращает уже отвергнутый запрос.</p>''', BASE_JS + '''
function draw(){const cap=+$('capacity').value,wait=+$('wait').value;let next=0;const counts={200:0,503:0,504:0};$('capacity-value').textContent=cap+' '+(cap===1?'запрос':'запроса');$('wait-value').textContent=wait+' мс';let rows='';for(let i=0;i<4;i++){const status=i>=cap?503:next>wait?504:200,start=next;counts[status]++;let explanation,track='';if(status===200){next+=60;explanation=`ожидание ${start} мс · работа ${start}–${start+60} мс`;track=interval(0,start,240,'wait')+interval(start,start+60,240,'work');}else if(status===504){explanation=`ожидание прервано в ${wait} мс`;track=interval(0,wait,240,'wait');}else{explanation='не принят: нет места';}rows+=`<div class="request-row" data-status="${status}"><div class="track-label">Запрос ${i+1}<span class="badge ${status===200?'':'warn'}">${status}</span></div><div class="timeline">${track}${status!==503?marker(wait,240):''}</div><div class="figure-caption">${explanation}</div></div>`;}$('schedule').innerHTML=rows+axis(240,[0,60,120,180,240]);$('counts').innerHTML=Object.entries(counts).map(([code,n])=>`<span class="stat">${code}: <b>${n}</b></span>`).join('');$('result').className='result'+(counts[503]+counts[504]?' warn':'');$('result').innerHTML=`<strong>${counts[200]} из 4 запросов выполнены</strong>${counts[503]} отклонены из-за вместимости; ${counts[504]} не дождались worker. Больше мест не гарантирует успех, если лимит ожидания короткий.`;}
document.querySelectorAll('input').forEach(el=>el.addEventListener('input',draw));draw();''')

    page("M14-L06", "Предложение модели проходит четыре проверки", "Выбери вызов инструмента и проследи, где исполнитель разрешит или остановит его. Это ручная модель проверок; настоящая LLM запускается в лабораторной.", '''
<div class="controls"><label class="control"><span class="label">Предложенный вызов</span><select id="action"><option value="allowed">read d1 — разрешённый</option><option value="foreign">read d2 — чужой документ</option><option value="extra">read d1 + session=s2</option><option value="repeat">read d1 — повторный вызов</option></select></label></div>
<pre id="proposal" aria-label="Аргументы вызова"></pre>
<div class="figure"><h2>Граница доверия: scope s1 задаёт сервер</h2><div id="pipeline" class="diagram-flow"></div><p class="figure-caption">Любой отказ останавливает путь до чтения данных. Повторный вызов использует тот же ключ операции.</p></div>
<div id="result" class="result" aria-live="polite"></div><p class="note">Корректный отказ проверяет ограничение исполнителя. Полезность выбора инструмента самой моделью оценивается отдельно.</p>''', BASE_JS + '''
const scenarios={allowed:{proposal:'{"tool":"read","document_id":"d1"}',steps:[['pass','Только разрешённые поля'],['pass','d1 входит в scope s1'],['pass','Ключ ещё не выполнен'],['pass','Прочитать d1']],result:'observation d1',reads:1},foreign:{proposal:'{"tool":"read","document_id":"d2"}',steps:[['pass','Только разрешённые поля'],['blocked','d2 вне scope s1'],['skipped','Не выполняется'],['skipped','Не выполняется']],result:'Отказ: чужой документ',reads:0},extra:{proposal:'{"tool":"read","document_id":"d1","session":"s2"}',steps:[['blocked','Лишнее поле session'],['skipped','Не выполняется'],['skipped','Не выполняется'],['skipped','Не выполняется']],result:'Отказ до проверки scope',reads:0},repeat:{proposal:'{"tool":"read","document_id":"d1"}',steps:[['pass','Только разрешённые поля'],['pass','d1 входит в scope s1'],['blocked','Ключ уже выполнен'],['skipped','Повторного чтения нет']],result:'repeated_call',reads:0}};
function draw(){const s=scenarios[$('action').value];$('proposal').textContent=s.proposal;$('pipeline').innerHTML=s.steps.map(([state,text],i)=>`<div class="flow-step ${state}" data-state="${state}"><span class="step-number">${i+1} / 4 · ${state==='pass'?'пройдено':state==='blocked'?'остановка':'пропущено'}</span><b>${['Схема','Доступ','Идемпотентность','Чтение'][i]}</b><p>${text}</p></div>`).join('');$('result').className='result'+(s.reads?'':' warn');$('result').innerHTML=`<strong>${s.result}</strong>Фактических чтений в этом сценарии: ${s.reads}. Модель не может расширить scope аргументами вызова.`;}$('action').addEventListener('input',draw);draw();''')

    page("M15-L06", "Когда пауза становится концом реплики?", "В записи две части речи, разделённые паузой 350 мс. Выбери порог: объединит ли детектор обе части или закроет первую слишком рано?", '''
<div class="controls"><label class="control"><span class="label">Порог тишины <output id="pause-value" for="pause">500 мс</output></span><input id="pause" type="range" min="100" max="900" step="50" value="500"></label></div>
<div class="figure"><div class="legend"><span>Речь</span><span class="pause">Тишина</span><span class="output">Открытый сегмент</span><span class="endpoint">Решение «конец»</span></div>
<div class="track-label">Входной звук <small>время, мс</small></div><div id="audio" class="timeline" aria-label="Речь 0–400 мс, пауза 400–750 мс, речь 750–1350 мс, тишина до 2350 мс"></div><div id="time-axis"></div>
<div id="segments" aria-label="Сегменты детектора"></div><ul id="events" class="event-list"></ul></div>
<div id="result" class="result" aria-live="polite"></div>
<p class="note">Учебный детектор проверяет тишину непрерывно: конец = последний момент речи + порог. В реальном потоке решение округляется до границы аудиоблока. Полоса показывает время открытого сегмента; сохранение или удаление тишины — отдельная настройка.</p>''', BASE_JS + '''
function draw(){const p=+$('pause').value,split=p<=350,ends=split?[400+p,1350+p]:[1350+p],starts=split?[0,750]:[0];$('pause-value').textContent=p+' мс';$('audio').innerHTML=interval(0,400,2350,'')+interval(400,750,2350,'silence')+interval(750,1350,2350,'')+interval(1350,2350,2350,'silence')+ends.map(t=>marker(t,2350)).join('');$('time-axis').innerHTML=axis(2350,[0,750,1350,2350]);$('segments').innerHTML=ends.map((end,i)=>`<div class="segment" data-end="${end}"><div class="track-label">Сегмент ${i+1}<small>${starts[i]}–${end} мс</small></div><div class="timeline">${interval(starts[i],end,2350,'buffer')}${marker(end,2350)}</div></div>`).join('');$('events').innerHTML=ends.map((end,i)=>`<li><b>${end} мс</b><span>закрывается сегмент ${i+1}${split&&i===0?' внутри паузы':''}</span></li>`).join('');$('result').className='result'+(split?' warn':'');$('result').innerHTML=split?`<strong>2 сегмента: реплика разорвана</strong>Внутренняя пауза 350 мс достигает порога ${p} мс. Детектор закрывает первую часть в 400 + ${p} = ${ends[0]} мс и открывает новую в 750 мс.`:`<strong>1 сегмент: обе части вместе</strong>Пауза 350 мс короче порога ${p} мс. После конца речи в 1350 мс детектор ждёт ещё ${p} мс; решение появляется в ${ends[0]} мс.`;}
$('pause').addEventListener('input',draw);draw();''')

    page("M16-L06", "Настоящая цитата ещё не доказывает вывод", "Выбери цитату и критерий. Проверка подстроки отвечает, было ли это сказано; смысловая проверка — подтверждает ли цитата нужное качество ответа.", '''
<blockquote class="source-quote" id="source"><span id="phrase0">Коллега внедрил кеш.</span> <span id="phrase1">Я проверил повторный запрос.</span></blockquote>
<div class="controls"><label class="control"><span class="label">Фрагмент для проверки</span><select id="fragment"><option value="0">Коллега внедрил кеш.</option><option value="1">Я проверил повторный запрос.</option><option value="2">Мы увеличили выручку.</option></select></label><label class="control"><span class="label">Что хотим подтвердить?</span><select id="criterion"><option value="action">Личное действие</option><option value="outcome">Наблюдаемый результат</option></select></label></div>
<div class="figure"><div id="evidence-flow"></div></div><div id="result" class="result" aria-live="polite"></div>
<p class="note">Третий фрагмент намеренно отсутствует в ответе: это контрпример для защиты. Ограниченный селектор в продукте должен выбирать только существующие фрагменты. Здесь нет автоматического балла кандидату.</p>''', BASE_JS + '''
function draw(){const k=+$('fragment').value,action=$('criterion').value==='action',found=k<2,valid=found&&k===1&&action;['Коллега внедрил кеш.','Я проверил повторный запрос.'].forEach((text,i)=>{$('phrase'+i).innerHTML=k===i?'<mark>'+text+'</mark>':text});const reason=!found?'В исходном ответе нет такой подстроки.':valid?'«Я проверил» прямо указывает на действие кандидата.':action?'«Коллега внедрил» описывает действие другого человека.':'Не сказано, что показала проверка или что изменилось после внедрения.';$('evidence-flow').innerHTML=`<div class="gate ${found?'':'blocked'}"><span>${found?'✓':'×'}</span><div><strong>1. Цитата присутствует: ${found?'да':'нет'}</strong><p>Проверяется точным совпадением с исходным ответом.</p></div></div><div class="gate ${valid?'':'blocked'}"><span>${valid?'✓':found?'?':'—'}</span><div><strong>2. Критерий ${valid?'подтверждён':found?'не подтверждён':'не проверяется'}</strong><p>${reason}</p></div></div>`;$('result').className='result'+(valid?'':' warn');$('result').innerHTML=`<strong>${valid?'Есть основание для критерия':found?'Не хватает основания для вывода':'Фрагмент отклонён до оценки'}</strong>${valid?'Личное действие описано. Измеренный эффект из этой цитаты вывести нельзя.':reason+' Не добавляй в отзыв сведения, которых нет в ответе.'}`;}
document.querySelectorAll('select').forEach(el=>el.addEventListener('input',draw));draw();''')

    page("M16-L07", "Уточнения не должны длиться бесконечно", "В интервью две темы. Предскажи, что произойдёт после ответа: уточнение, переход к следующей теме или завершение. Длина ответа здесь — учебная эвристика, а не оценка кандидата.", '''
<div class="controls"><label class="control"><span class="label">Уточнений на тему <output id="limit-value" for="limit">1</output></span><input id="limit" type="range" min="0" max="2" value="1"><small>Смена лимита начинает опыт заново</small></label><label class="control"><span class="label">Ответ кандидата</span><select id="answer"><option value="short">Короткий / «не знаю»</option><option value="long">Длинный</option><option value="refuse">«Не хочу отвечать»</option></select></label></div>
<div class="buttons"><button id="step">Принять ответ</button><button id="reset" class="secondary">Начать заново</button></div>
<div class="figure"><div id="states" class="states"></div><div id="counters" class="stat-row"></div></div><div id="result" class="result" aria-live="polite"></div>
<details><summary>История переходов</summary><ol id="history" class="history"></ol></details>
<p class="note">Отказ отвечать сразу завершает текущую тему. После состояния finished новые ответы не принимаются. Состояние хранится только до перезагрузки опыта.</p>''', BASE_JS + '''
let state={topic:0,turn:0,clarify:0,history:[],last:'Ожидается первый ответ по теме 1.'};
function draw(){const limit=+$('limit').value;$('limit-value').textContent=limit;$('states').innerHTML=['Тема 1','Тема 2','Finished'].map((name,i)=>`<div class="state ${i===state.topic?'current':i<state.topic?'done':''}" data-state="${i===state.topic?'current':i<state.topic?'done':'pending'}"><b>${name}</b><small>${i===state.topic?(i===2?'завершено':'текущая'):i<state.topic?'пройдена':'впереди'}</small></div>`).join('');$('counters').innerHTML=`<span class="stat">Ответов: <b>${state.turn} / ${2*(1+limit)}</b></span><span class="stat">Уточнений в теме: <b>${state.clarify} / ${limit}</b></span>`;$('result').innerHTML=`<strong>${state.last}</strong>${state.topic>=2?'Интервью закончено; кнопка приёма ответа отключена.':`Следующий ответ относится к теме ${state.topic+1}. Максимум для всего интервью: ${2*(1+limit)} ответа.`}`;$('history').innerHTML=state.history.map(s=>'<li>'+s+'</li>').join('')||'<li>Ответы ещё не приняты.</li>';$('step').disabled=state.topic>=2;}
function reset(){state={topic:0,turn:0,clarify:0,history:[],last:'Ожидается первый ответ по теме 1.'};draw();}
$('step').addEventListener('click',()=>{if(state.topic>=2)return;const kind=$('answer').value,topic=state.topic+1;state.turn++;if(kind==='short'&&state.clarify<+$('limit').value){state.clarify++;state.last=`Тема ${topic}: уточнение ${state.clarify}.`;}else{state.topic++;state.clarify=0;state.last=kind==='refuse'?`Отказ принят. Тема ${topic} закрыта.`:kind==='short'?`Лимит уточнений исчерпан. Тема ${topic} закрыта.`:`Ответ принят. Тема ${topic} закрыта.`;}state.history.push(`Ход ${state.turn}. ${state.last}`);draw();});$('reset').addEventListener('click',reset);$('limit').addEventListener('input',reset);$('answer').addEventListener('input',draw);draw();''')

    page("M16-L08", "У приёмки есть обязательные условия", "Отметь, какие свидетельства есть у учебного решения. Попробуй добавить критическую ошибку при всех трёх положительных результатах.", '''
<div class="check-list">
<label class="check-item"><input id="run" type="checkbox" checked><span>Продукт запускается<small>Наблюдаемое выполнение</small></span></label>
<label class="check-item"><input id="explain" type="checkbox" checked><span>Механизм объяснён<small>Понимание решения</small></span></label>
<label class="check-item"><input id="new" type="checkbox" checked><span>Новый случай решён<small>Самостоятельный перенос</small></span></label>
<label class="check-item"><input id="critical" type="checkbox"><span>Есть критическая ошибка<small>Например, утечка тестовых данных</small></span></label>
</div><div class="figure"><h2 id="evidence-count">Свидетельства: 3 из 3</h2><div class="progress-track"><div id="evidence-bar" class="progress-fill"></div></div><div id="gates"></div></div>
<div id="result" class="result" aria-live="polite"></div><p class="note">Это расчёт приёмки вымышленного решения. Он не записывает твой прогресс и не подтверждает профессиональный грейд. Критические ошибки перечисляются в рубрике конкретного задания.</p>''', BASE_JS + '''
function draw(){const ids=['run','explain','new'],count=ids.filter(id=>$(id).checked).length,critical=$('critical').checked,ok=count===3&&!critical;$('evidence-count').textContent=`Свидетельства: ${count} из 3`;$('evidence-bar').style.width=(100*count/3)+'%';$('gates').innerHTML=`<div class="gate ${count===3?'':'blocked'}"><span>${count===3?'✓':'×'}</span><div><strong>Все три основания</strong><p>${count===3?'Есть продукт, объяснение и решение нового случая.':'Не хватает: '+ids.filter(id=>!$(id).checked).map(id=>({run:'работающего продукта',explain:'объяснения',new:'нового самостоятельного случая'}[id])).join(', ')+'.'}</p></div></div><div class="gate ${critical?'blocked':''}"><span>${critical?'×':'✓'}</span><div><strong>Критических ошибок нет</strong><p>${critical?'Условие нарушено — приёмка блокируется.':'Условие выполнено в этом примере.'}</p></div></div>`;$('result').className='result'+(ok?'':' warn');$('result').innerHTML=`<strong>${ok?'В этом примере приёмка пройдена':'Требуется новая попытка'}</strong>${critical?'Даже 3 из 3 свидетельств не компенсируют критическую ошибку. Сначала исправь её и проведи новую проверку.':ok?'Оба обязательных условия выполнены одновременно.':'Дополни отсутствующее свидетельство; сумма остальных результатов его не заменяет.'}`;}
document.querySelectorAll('input').forEach(el=>el.addEventListener('input',draw));draw();''')


